function statusColor(status: string): string {
  switch (status.toUpperCase()) {
    case 'APPROVED':
    case 'ACTIVE':
    case 'DISBURSED':
      return 'green';
    case 'PENDING':
    case 'REVIEW':
      return 'blue';
    case 'REJECTED':
    case 'CLOSED':
      return 'red';
    default:
      return 'default';
  }
}

function statusText(status: string): string {
  switch (status.toUpperCase()) {
    case 'APPROVED':
      return '已批准';
    case 'ACTIVE':
      return '活跃';
    case 'DISBURSED':
      return '已放款';
    case 'PENDING':
      return '待审核';
    case 'REVIEW':
      return '审核中';
    case 'REJECTED':
      return '已拒绝';
    case 'CLOSED':
      return '已结清';
    default:
      return status;
  }
}

